    public interface IStreamDeckAction
    {
        string Name { get; }
        string Description { get; }
        string Icon { get; }
        void Execute(); // Dla klikniecia
        void ExecuteAnalog(bool direction); // true = w prawo / glosniej, false = w lewo / ciszej
    }
